/**
 * Four Pillars Counseling PLLC
 * /services/couples/index.php
 *
 * Geo-routing logic: detects visitor's state via IP geolocation API.
 * Arkansas visitors receive "relationship counseling" terminology per AR
 * Board of Examiners in Counseling licensing requirements.
 * Texas visitors (and all others) receive the standard approved copy.
 *
 * A visible self-correction toggle is included on every render for
 * compliance posture — demonstrates good-faith effort to licensing boards.
 */

// ── GEO DETECTION ────────────────────────────────────────────────────────────

$visitor_state = 'TX'; // default
$geo_confident = false;
$geo_error     = false;

$ip = $_SERVER['HTTP_CF_CONNECTING_IP']   // Cloudflare (not used here but safe to check)
   ?? $_SERVER['HTTP_X_FORWARDED_FOR']
   ?? $_SERVER['REMOTE_ADDR']
   ?? '';

// Strip any comma-separated IPs (X-Forwarded-For can contain chains)
if (strpos($ip, ',') !== false) {
    $ip = trim(explode(',', $ip)[0]);
}

// Allow manual override via query string (?state=AR or ?state=TX)
// This powers the self-correction toggle and allows easy QA testing.
if (isset($_GET['state']) && in_array(strtoupper($_GET['state']), ['TX', 'AR'])) {
    $visitor_state = strtoupper($_GET['state']);
    $geo_confident = true;
} elseif (!empty($ip) && filter_var($ip, FILTER_VALIDATE_IP)) {
    // Use ip-api.com free tier (no key required, 1000 req/min)
    $api_url  = 'http://ip-api.com/json/' . urlencode($ip) . '?fields=status,regionName,region';
    $context  = stream_context_create(['http' => ['timeout' => 2]]);
    $response = @file_get_contents($api_url, false, $context);

    if ($response !== false) {
        $data = json_decode($response, true);
        if (isset($data['status']) && $data['status'] === 'success') {
            $region_code = strtoupper($data['region'] ?? '');
            if ($region_code === 'AR') {
                $visitor_state = 'AR';
            } else {
                $visitor_state = 'TX'; // all non-AR visitors get TX copy
            }
            $geo_confident = true;
        } else {
            $geo_error = true;
        }
    } else {
        $geo_error = true;
    }
}

$is_ar = ($visitor_state === 'AR');

// ── CONTENT VARIABLES ─────────────────────────────────────────────────────────
// All Arkansas substitutions are centralized here.

// Page title
$page_title = $is_ar
    ? 'Relationship Counseling | Four Pillars Counseling, PLLC'
    : 'Couples Counseling | Four Pillars Counseling, PLLC';

// Nav link label (active page)
$nav_label = $is_ar ? 'Relationship Counseling' : 'Couples Counseling';

// Hero breadcrumb
$breadcrumb_label = $is_ar ? 'Relationship Counseling' : 'Couples Counseling';

// Hero sub
$hero_sub = $is_ar
    ? 'Whether you're navigating a rough patch, building something stronger before you commit, or simply looking to communicate better — relationship counseling provides the structure and support to get there.'
    : 'Whether you're navigating a rough patch, building something stronger before you commit, or simply looking to communicate better — couples counseling provides the structure and support to get there.';

// Section 1 label
$s1_label = $is_ar ? 'What Relationship Counseling Is For' : 'What Couples Counseling Is For';

// Section 1 body paragraphs
$s1_p2 = $is_ar
    ? 'Relationship counseling at Four Pillars is not reserved for relationships in crisis. Many of the couples who do this work are not on the verge of separation. They are people who value their relationship enough to invest in better communication, deeper understanding, and a stronger foundation for the future.'
    : 'Couples counseling at Four Pillars is not reserved for relationships in crisis. Many of the couples who do this work are not on the verge of separation. They are people who value their relationship enough to invest in better communication, deeper understanding, and a stronger foundation for the future.';

// Section 2 body paragraphs
$s2_p1 = $is_ar
    ? 'Four Pillars takes an integrative approach to relationship counseling. That means no single therapeutic model is followed rigidly. Instead, the practice draws on a range of evidence-based methods, intentionally selecting and combining approaches based on what your relationship actually needs rather than fitting your situation to a predetermined framework.'
    : 'Four Pillars takes an integrative approach to couples counseling. That means no single therapeutic model is followed rigidly. Instead, the practice draws on a range of evidence-based methods, intentionally selecting and combining approaches based on what your relationship actually needs rather than fitting your situation to a predetermined framework.';

// Section 3 body (premarital — marital language is acceptable here per standing copy rules)
// No AR substitution needed in Section 3; it already uses "couples" only in the approved marital context.

// Section 4 label
$s4_label = $is_ar ? 'Where and How We Meet' : 'Where and How We Meet'; // same both states

// Toggle URLs
$toggle_ar_url = '?state=AR';
$toggle_tx_url = '?state=TX';

// Toggle notice text
if ($is_ar) {
    $toggle_notice = 'Showing <strong>Arkansas</strong> version of this page.';
    $toggle_action = 'Not in Arkansas? <a href="' . $toggle_tx_url . '">View Texas version</a>';
} else {
    $toggle_notice = 'Showing <strong>Texas</strong> version of this page.';
    $toggle_action = 'Located in Arkansas? <a href="' . $toggle_ar_url . '">View Arkansas version</a>';
}

